/**
 * The contract between the UI and *any* data source.
 *
 * Today `MockFinanceApi` implements it over localStorage. When the FastAPI
 * backend is ready, add an `HttpFinanceApi` that implements the same interface
 * and swap the export in `api/index.ts`. Pages and the store never import the
 * mock directly.
 *
 * Mutations that create money-moving records accept an `idempotencyKey`
 * generated by the client *before* the request. Retrying with the same key
 * must be safe. This mirrors what the backend will need to enforce.
 */
import type {
  Account,
  AccountType,
  Budget,
  Category,
  CategoryType,
  CurrencyCode,
  FinanceSnapshot,
  Id,
  ImportJob,
  ISODate,
  MinorUnits,
  MonthKey,
  RecurrenceFrequency,
  RecurringRule,
  RecurringRuleStatus,
  Transaction,
  TransactionType,
  Transfer,
} from '@/domain'

// ---------------------------------------------------------------------------
// Inputs
// ---------------------------------------------------------------------------

export interface AccountInput {
  name: string
  type: AccountType
  currency: CurrencyCode
  openingBalance: MinorUnits
  description: string | null
  color: string | null
}

export interface TransactionInput {
  type: Exclude<TransactionType, 'transfer'>
  amount: MinorUnits
  description: string
  accountId: Id
  categoryId: Id
  date: ISODate
  notes: string | null
}

export interface TransferInput {
  sourceAccountId: Id
  destinationAccountId: Id
  amount: MinorUnits
  date: ISODate
  description: string | null
}

export interface CategoryInput {
  name: string
  type: CategoryType
  color: string
  icon: string | null
}

export interface BudgetInput {
  name: string | null
  categoryId: Id
  amount: MinorUnits
  currency: CurrencyCode
  startMonth: MonthKey
  endMonth: MonthKey | null
  warningThreshold: number | null
}

export interface RecurringRuleInput {
  description: string
  type: Exclude<TransactionType, 'transfer'>
  amount: MinorUnits
  accountId: Id
  categoryId: Id
  frequency: RecurrenceFrequency
  interval: number
  startDate: ISODate
  endDate: ISODate | null
  notes: string | null
}

/** A row that already passed client-side validation and column mapping. */
export interface ImportRowInput {
  /** 1-based row number in the source file, for error reporting. */
  row: number
  date: ISODate
  description: string
  amount: MinorUnits
  type: Exclude<TransactionType, 'transfer'>
  accountId: Id
  categoryId: Id | null
  notes: string | null
}

export interface ImportInput {
  fileName: string
  /** Default account when a row has none. */
  accountId: Id | null
  rows: ImportRowInput[]
  /** Rows the user chose to skip (e.g. flagged duplicates). */
  skippedRows: number
  /** Rows that failed client-side validation (reported, not imported). */
  invalidRows: { row: number; field: string | null; message: string }[]
}

// ---------------------------------------------------------------------------
// Responses
// ---------------------------------------------------------------------------

export interface TransferResult {
  transfer: Transfer
  /** Both legs: [source (out), destination (in)] */
  transactions: Transaction[]
}

export interface ImportResult {
  job: ImportJob
  transactions: Transaction[]
}

export interface DeleteCategoryResult {
  /** Transactions moved to another category (empty when none). */
  reassignedTransactionIds: Id[]
}

export interface TransferLookup {
  found: boolean
  transfer: Transfer | null
  transactions: Transaction[]
}

// ---------------------------------------------------------------------------
// The interface
// ---------------------------------------------------------------------------

export interface FinanceApi {
  // Snapshot
  loadSnapshot(): Promise<FinanceSnapshot>
  /** Replace everything with the sample dataset. */
  resetToSample(): Promise<FinanceSnapshot>
  /** Replace everything with an empty dataset (default categories only). */
  resetToEmpty(): Promise<FinanceSnapshot>

  // Accounts
  createAccount(input: AccountInput): Promise<Account>
  updateAccount(id: Id, input: AccountInput): Promise<Account>
  setAccountStatus(id: Id, status: Account['status']): Promise<Account>
  /** Rejects with `conflict` when the account has transactions. */
  deleteAccount(id: Id): Promise<void>

  // Transactions
  createTransaction(input: TransactionInput, idempotencyKey: string): Promise<Transaction>
  /** Reconcile a create whose outcome was unknown. null → never committed. */
  lookupTransaction(idempotencyKey: string): Promise<Transaction | null>
  updateTransaction(id: Id, input: TransactionInput): Promise<Transaction>
  deleteTransaction(id: Id): Promise<void>

  // Transfers
  createTransfer(input: TransferInput, idempotencyKey: string): Promise<TransferResult>
  /** Reconcile an operation whose outcome was unknown. */
  lookupTransfer(idempotencyKey: string): Promise<TransferLookup>
  /** Removes the transfer and both legs. */
  deleteTransfer(id: Id): Promise<void>

  // Categories
  createCategory(input: CategoryInput): Promise<Category>
  updateCategory(id: Id, input: CategoryInput): Promise<Category>
  setCategoryStatus(id: Id, status: Category['status']): Promise<Category>
  /**
   * Deletes a category. If it has transactions, `reassignToCategoryId` is
   * required, otherwise rejects with `conflict`.
   */
  deleteCategory(id: Id, reassignToCategoryId: Id | null): Promise<DeleteCategoryResult>

  // Budgets
  createBudget(input: BudgetInput): Promise<Budget>
  updateBudget(id: Id, input: BudgetInput): Promise<Budget>
  deleteBudget(id: Id): Promise<void>

  // Recurring rules
  createRecurringRule(input: RecurringRuleInput): Promise<RecurringRule>
  updateRecurringRule(id: Id, input: RecurringRuleInput): Promise<RecurringRule>
  setRecurringRuleStatus(id: Id, status: Extract<RecurringRuleStatus, 'active' | 'paused' | 'cancelled'>): Promise<RecurringRule>
  deleteRecurringRule(id: Id): Promise<void>

  // Import
  runImport(input: ImportInput, idempotencyKey: string): Promise<ImportResult>
  /** Reconcile an import whose outcome was unknown. null → never committed. */
  lookupImport(idempotencyKey: string): Promise<ImportResult | null>
}
